python3 << 'EOF'
import math

guesses = [64, 96, 80, 88, 84, 82, 81]
responses = ["higher", "lower", "higher", "lower", "lower", "lower", "higher"]

def likelihood(s, guesses, responses):
    prob = 1.0
    for g, r in zip(guesses, responses):
        if s == g:
            if r == "equals":
                prob *= 1.0
            else:
                return 0.0  # Impossible to get non-equals when s == g
        elif s > g:
            if r == "higher":
                prob *= 0.7
            else:  # r == "lower" (noise)
                prob *= 0.3
        else:  # s < g
            if r == "lower":
                prob *= 0.7
            else:  # r == "higher" (noise)
                prob *= 0.3
    return prob

# Compute likelihood for all s
likelihoods = []
for s in range(1, 129):
    l = likelihood(s, guesses, responses)
    likelihoods.append((s, l))

# Sort by likelihood descending
likelihoods.sort(key=lambda x: x[1], reverse=True)

# Print top 10
print("Top 10 most likely secrets:")
for s, l in likelihoods[:10]:
    print(f"  s={s}, likelihood={l:.6f}")

# Also print some candidates around the expected range
print("\nLikelihoods for s=75 to s=90:")
for s in range(75, 91):
    l = likelihood(s, guesses, responses)
    print(f"  s={s}, likelihood={l:.6f}")
