python3 << 'EOF'
import json

# Observed responses
observed = ["lower", "higher", "lower", "higher", "higher", "higher", "higher"]
guesses = [64, 32, 48, 40, 44, 46, 47]

# For each possible secret, compute the number of flips needed
results = []
for secret in range(1, 129):
    flips = 0
    possible = True
    for guess, obs in zip(guesses, observed):
        if guess < secret:
            true_resp = "higher"
        elif guess > secret:
            true_resp = "lower"
        else:
            true_resp = "equals"

        if true_resp == "equals":
            if obs != "equals":
                possible = False
                break
        else:
            if obs != true_resp:
                flips += 1

    if possible:
        results.append((secret, flips))

# Sort by number of flips
results.sort(key=lambda x: x[1])
print("Secrets sorted by flips needed:")
for secret, flips in results[:20]:
    print(f"  Secret {secret}: {flips} flips")
EOF

