python3 << 'EOF'
import json

# My guesses and responses
guesses = [64, 32, 48, 56, 60, 58, 57]
responses = ["lower", "higher", "higher", "higher", "lower", "lower", "higher"]

noise_prob = 0.3
correct_prob = 0.7

# For each possible secret, compute likelihood
likelihoods = {}
for secret in range(1, 129):
    log_likelihood = 0.0
    possible = True
    for guess, response in zip(guesses, responses):
        if guess < secret:
            true_response = "higher"
        elif guess > secret:
            true_response = "lower"
        else:
            true_response = "equals"

        if true_response == "equals":
            # If true is equals, we must get "equals" (no noise applies)
            if response == "equals":
                pass  # probability 1
            else:
                possible = False
                break
        else:
            # true_response is "higher" or "lower"
            if response == true_response:
                # Correct response
                log_likelihood += __import__('math').log(correct_prob)
            else:
                # Flipped response (noise)
                log_likelihood += __import__('math').log(noise_prob)

    if possible:
        likelihoods[secret] = log_likelihood

# Sort by likelihood (higher is better)
sorted_targets = sorted(likelihoods.items(), key=lambda x: x[1], reverse=True)

print("Top 10 most likely targets:")
for target, ll in sorted_targets[:10]:
    prob = __import__('math').exp(ll)
    print(f"  Target {target}: log-likelihood={ll:.4f}, likelihood={prob:.6f}")
EOF

