python3 << 'EOF'
import json

# My guesses and responses
guesses = [64, 32, 16, 24, 28, 30, 29, 31]
responses = ["lower", "lower", "higher", "higher", "higher", "lower", "higher", "higher"]

# For each possible secret, compute the likelihood
best_secret = None
best_log_likelihood = float('-inf')

for secret in range(1, 129):
    log_likelihood = 0
    valid = True

    for g, r in zip(guesses, responses):
        if g == secret:
            # Should have been "equals" but wasn't - impossible
            valid = False
            break

        if g < secret:
            # True response should be "higher"
            if r == "higher":
                log_likelihood += -0.458  # log(0.7)
            else:  # r == "lower"
                log_likelihood += -1.204  # log(0.3)
        else:  # g > secret
            # True response should be "lower"
            if r == "lower":
                log_likelihood += -0.458  # log(0.7)
            else:  # r == "higher"
                log_likelihood += -1.204  # log(0.3)

