import json

# My guesses and responses
guesses = [64, 32, 48, 56, 60, 58, 57]
responses = ["lower", "higher", "higher", "higher", "lower", "lower", "lower"]

# Compute likelihood for each possible secret
likelihoods = {}
for secret in range(1, 129):
    log_likelihood = 0.0
    for g, r in zip(guesses, responses):
        if g < secret:
            true_response = "higher"
        elif g > secret:
            true_response = "lower"
        else:
            true_response = "equals"

        if true_response == "equals":
            if r == "equals":
                log_likelihood += 0  # log(1) = 0
            else:
                log_likelihood += float('-inf')  # impossible
        else:
            if r == true_response:
                log_likelihood += -0.457  # log(0.7) ≈ -0.357
            else:
                log_likelihood += -1.204  # log(0.3) ≈ -1.204

    # Actually let me use probabilities instead of log for simplicity
    prob = 1.0
    for g, r in zip(guesses, responses):
        if g < secret:
            true_response = "higher"
        elif g > secret:
            true_response = "lower"
        else:
            true_response = "equals"

        if true_response == "equals":
            if r == "equals":
                prob *= 1.0
            else:
                prob = 0.0
                break
        else:
            if r == true_response:
                prob *= 0.7
            else:
                prob *= 0.3
    likelihoods[secret] = prob

# Sort by likelihood
sorted_likelihoods = sorted(likelihoods.items(), key=lambda x: -x[1])
print("Top 10 most likely secrets:")
for s, p in sorted_likelihoods[:10]:
    print(f"  {s}: {p:.6f}")

print("\nLikelihoods for 54-60:")
for s in range(54, 61):
    print(f"  {s}: {likelihoods[s]:.6f}")
